struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    struct page **pages;
    size_t nr_pages, i;
    ssize_t ret;
    size_t nr_segs;
    size_t offset = 0;

    nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (!nr_pages)
        return ERR_PTR(-EINVAL);

    pages = (struct page **) __get_free_pages(gfp_mask, get_order(nr_pages * sizeof(struct page)));
    if (!pages)
        return ERR_PTR(-ENOMEM);

    nr_segs = 0;
    ret = 0;

    iov_iter_init(iter);
    while (iov_iter_count(iter)) {
        struct page *page;
        size_t len = iov_iter_iovec(iter)->iov_len;
        size_t offset_in_iovec = 0;
        size_t page_idx = nr_segs / BIO_MAX_PAGES;

        if (page_idx >= nr_pages)
            break;

        while (len) {
            size_t chunk = min(len, (size_t)PAGE_SIZE);
            struct page *p = NULL;

            p = iov_iter_get_pages(iter, pages + page_idx, chunk, 1, &offset_in_iovec);
            if (!p) {
                ret = -EFAULT;
                goto out;
            }

            len -= chunk;
            offset_in_iovec = 0;
            nr_segs++;
            page_idx = nr_segs / BIO_MAX_PAGES;
            if (page_idx >= nr_pages) {
                ret = -ENOMEM;
                goto out;
            }
        }
    }

    if (ret)
        goto out;

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio) {
        ret = -ENOMEM;
        goto out;
    }

    bio->bi_flags |= BIO_USER_MAPPED;

    for (i = 0; i < nr_pages; i++) {
        struct page *page = pages[i];
        bio_add_page(bio, page, PAGE_SIZE, offset);
        offset = 0;
    }

    bio_set_pages(bio, pages, nr_pages);
    bio->bi_iter.bi_size = iter->count;

    return bio;

out:
    while (nr_segs--) {
        struct page *page = pages[nr_segs / BIO_MAX_PAGES];
        if (page)
            put_page(page);
    }
    free_pages((unsigned long) pages, get_order(nr_pages * sizeof(struct page)));
    if (bio)
        bio_put(bio);
    return ERR_PTR(ret);
}

struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    unsigned int nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    struct bio *bio;
    struct page **pages;
    size_t iter_pos;
    int i = 0;
    int ret;

    if (nr_pages == 0)
        return ERR_PTR(-EFAULT);

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    iov_iter_init(&iter->iov, iter->type, iter->iov, iter->nr_segs, iter->count);
    iter_pos = 0;

    while (iter_pos < iter->count && i < nr_pages) {
        struct page *page;

        page = iov_iter_get_pages(iter, pages + i, 0, BIO_MAX_PAGES - i, &ret);
        if (ret <= 0) {
            if (!ret)
                ret = -EFAULT;
            goto error;
        }

        iter_pos += ret;
        i += 1;
    }

    for (i = 0; i < nr_pages; i++) {
        struct bio_vec bv;

        bv.bv_page = pages[i];
        bv.bv_len = bio_sectors_to_bytes(1);
        bv.bv_offset = 0;

        ret = bio_add_page(bio, pages[i], bv.bv_len, bv.bv_offset);
        if (ret < bv.bv_len) {
            ret = -EFAULT;
            goto error;
        }
    }

    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    kfree(pages);
    return bio;

error:
    for (i = 0; i < nr_pages; i++) {
        put_page(pages[i]);
    }
    kfree(pages);
    bio_put(bio);
    return ERR_PTR(ret);
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned int nr_pages, i;
    struct page **pages;
    ssize_t ret;

    nr_pages = iov_iter_npages(iter, IOV_MAX);
    if (nr_pages == 0)
        return ERR_PTR(-EINVAL);

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    ret = iov_iter_get_pages(iter, pages, nr_pages, &bio->bi_vcnt, &bio->bi_size);
    if (ret < 0) {
        kfree(pages);
        bio_put(bio);
        return ERR_PTR(ret);
    }

    for (i = 0; i < bio->bi_vcnt; i++) {
        bio_add_page(bio, pages[i], iter->iov[i].iov_len, iter->iov[i].iov_base % PAGE_SIZE);
    }

    kfree(pages);

    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    return bio;
}

struct bio *bio_map_user_iovec(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    struct page **pages;
    size_t nr_pages = 0, i;
    ssize_t ret;

    bio = bio_alloc(gfp_mask, 0);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    iov_iter_init(iter);
    ret = iov_iter_get_pages_alloc(iter, &pages, &nr_pages, SIZE_MAX, gfp_mask);
    if (IS_ERR_VALUE(ret)) {
        bio_put(bio);
        return ERR_PTR(ret);
    }

    for (i = 0; i < nr_pages; ++i) {
        struct bio_vec bv;

        bv.bv_page = pages[i];
        bv.bv_len = min((size_t)PAGE_SIZE, iter->count);
        bv.bv_offset = iter->iov->iov_base - page_address(pages[i]);

        bio_add_page(bio, pages[i], bv.bv_len, bv.bv_offset);
        iter->iov++;
        iter->count -= bv.bv_len;
    }

    kfree(pages);

    if (iter->count != 0) {
        bio_put(bio);
        return ERR_PTR(-EFAULT);
    }

    bio->bi_opf |= REQ_USER_MAPPED;

    return bio;
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned long nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    struct page **pages;
    size_t offset;
    ssize_t bytes;
    int i = 0;
    struct iov_iter i_iter = *iter;

    if (!nr_pages)
        return ERR_PTR(-ENOMEM);

    bio = bio_kmalloc(gfp_mask, 1 << BIO_RESET_PAGES);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    bio->bi_io_vec = kmalloc_array(1 << BIO_RESET_PAGES, sizeof(struct bio_vec), gfp_mask);
    if (!bio->bi_io_vec) {
        kfree(pages);
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    while (iov_iter_count(&i_iter)) {
        struct page *page;
        size_t offset_in_page;
        size_t size;

        if (i >= nr_pages)
            break;

        size = iov_iter_get_pages(&i_iter, &pages[i], BIO_MAX_SECTORS << 9, 1 << (BIO_RESET_PAGES - 1), &offset);
        if (!size)
            break;

        page = pages[i];
        offset_in_page = offset;

        bio_add_page(bio, page, size, offset_in_page);

        i++;
    }

    bio->bi_vcnt = i;
    bio->bi_size = i_iter.count;

    if (bio->bi_vcnt == 0) {
        kfree(pages);
        kfree(bio->bi_io_vec);
        bio_put(bio);
        return ERR_PTR(-EFAULT);
    }

    bio->bi_flags |= 1 << BIO_USER_MAPPED;

    return bio;
}
